package com.cardvision.ai;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.net.Uri;
import com.google.mlkit.vision.common.InputImage;
import com.google.mlkit.vision.text.TextRecognition;
import com.google.mlkit.vision.text.latin.TextRecognizerOptions;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

public class MainActivity extends Activity {
  LinearLayout root, content;
  JSONArray cards;
  int blue=Color.rgb(38,99,235), ink=Color.rgb(22,34,57);
  android.content.SharedPreferences prefs;
  @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("cards",MODE_PRIVATE);load();home();}
  void load(){try{cards=new JSONArray(prefs.getString("items","[]"));}catch(Exception e){cards=new JSONArray();}}
  void save(){prefs.edit().putString("items",cards.toString()).apply();}
  TextView label(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(ink);t.setPadding(8,12,8,12);if(bold)t.setTypeface(null,1);return t;}
  void screen(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.rgb(246,248,253));setContentView(root);TextView h=label(title,26,true);h.setPadding(24,32,24,20);root.addView(h);ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setPadding(20,8,20,20);content.setOrientation(1);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
  void button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setTextColor(blue);content.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->action.run());}
  EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);content.addView(e);return e;}
  void message(String text){new AlertDialog.Builder(this).setMessage(text).setPositiveButton("Tamam",null).show();}
  void home(){screen("CardVision AI");content.addView(label("Kartlarını keşfet, koleksiyonunu yönet",16,false));button("📷 Kart tara (OCR)",()->scan());button("＋ Kart ekle",()->add());button("▦ Koleksiyonum ("+cards.length()+")",()->collection(""));button("⌕ Kart ara",()->search());button("▤ Klasörler / etiketler",()->folders());button("↧ JSON yedek içe aktar",()->importBackup());button("☆ Favoriler",()->favorites());button("◷ Portföy değeri",()->portfolio());button("⇧ Koleksiyonu paylaş",()->export());button("⚙ Entegrasyon durumu",()->status());}
  void scan(){screen("Kart tara");content.addView(label("Kartın fotoğrafını galeriden seç. Cihaz üzerinde yazılar okunacak; oyuncu ve kart varyantı otomatik doğrulanmaz.",16,false));button("Fotoğraf seç",()->{Intent i=new Intent(Intent.ACTION_GET_CONTENT);i.setType("image/*");startActivityForResult(Intent.createChooser(i,"Kart fotoğrafı"),401);});button("← Ana sayfa",()->home());}
  @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=401||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{InputImage image=InputImage.fromFilePath(this,uri);com.google.mlkit.vision.text.TextRecognizer recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);recognizer.process(image).addOnSuccessListener(text->{screen("Okunan kart yazıları");String value=text.getText();content.addView(label(value.isEmpty()?"Yazı bulunamadı.":"OCR sonucu:\\n"+value,16,false));button("Kartı koleksiyona ekle",()->addFromScan(value));button("← Ana sayfa",()->home());recognizer.close();}).addOnFailureListener(err->{message("OCR hatası: "+err.getMessage());recognizer.close();});}catch(Exception e){message("Fotoğraf açılamadı: "+e.getMessage());}}
  void addFromScan(String value){screen("Taramadan kart ekle");EditText name=field("Kart adı / oyuncu"),sport=field("Spor veya TCG"),brand=field("Marka / set"),year=field("Yıl"),number=field("Kart numarası"),price=field("Tahmini değer (USD)");name.setText(value.length()>120?value.substring(0,120):value);button("Koleksiyona kaydet",()->{if(name.getText().toString().trim().isEmpty()){message("Kart adı gerekli");return;}try{JSONObject o=new JSONObject();o.put("id",UUID.randomUUID().toString());o.put("name",name.getText().toString().trim());o.put("sport",sport.getText().toString());o.put("brand",brand.getText().toString());o.put("year",year.getText().toString());o.put("number",number.getText().toString());o.put("price",price.getText().toString());o.put("ocr",value);o.put("favorite",false);cards.put(o);save();home();}catch(Exception e){message("Kaydedilemedi");}});}
  void add(){screen("Yeni kart");EditText name=field("Kart / oyuncu adı"),sport=field("Spor veya TCG"),brand=field("Marka / set"),year=field("Yıl"),number=field("Kart numarası"),variant=field("Varyant / parallel"),price=field("Tahmini değer (USD)"),cost=field("Alış fiyatı (USD)"),folder=field("Klasör"),notes=field("Notlar"),grade=field("Kondisyon / grading");button("Kartı kaydet",()->{String n=name.getText().toString().trim();if(n.isEmpty()){message("Kart adı gerekli");return;}try{JSONObject o=new JSONObject();o.put("id",UUID.randomUUID().toString());o.put("name",n);o.put("sport",sport.getText());o.put("brand",brand.getText());o.put("year",year.getText());o.put("number",number.getText());o.put("variant",variant.getText());o.put("price",price.getText().toString());o.put("cost",cost.getText().toString());o.put("folder",folder.getText().toString());o.put("notes",notes.getText().toString());o.put("grade",grade.getText().toString());o.put("favorite",false);cards.put(o);save();home();}catch(Exception e){message("Kaydedilemedi");}});button("← Geri",()->home());}
  void search(){screen("Kart ara");EditText q=field("Oyuncu, marka, yıl, seri");button("Ara",()->collection(q.getText().toString()));button("← Geri",()->home());}
  void collection(String query){screen("Koleksiyonum");int count=0;for(int i=0;i<cards.length();i++){JSONObject o=cards.optJSONObject(i);if(o==null||!o.toString().toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;count++;final String id=o.optString("id");content.addView(label(o.optString("name")+"  ·  "+o.optString("year")+" "+o.optString("brand")+"  ·  $"+o.optString("price"),17,true));content.addView(label("Klasör: "+o.optString("folder","—")+"  •  Kondisyon: "+o.optString("grade","—")+"\nNot: "+o.optString("notes",""),13,false));button("☆ Favori / kaldır",()->toggle(id));button("Kartı düzenle",()->edit(id));button("Sil",()->delete(id));}if(count==0)content.addView(label("Henüz eşleşen kart yok.",15,false));button("＋ Yeni kart",()->add());button("← Ana sayfa",()->home());}
  void toggle(String id){for(int i=0;i<cards.length();i++){JSONObject o=cards.optJSONObject(i);if(o!=null&&id.equals(o.optString("id"))){try{o.put("favorite",!o.optBoolean("favorite"));}catch(Exception ignored){}break;}}save();collection("");}
  void delete(String id){new AlertDialog.Builder(this).setMessage("Kart silinsin mi?").setNegativeButton("İptal",null).setPositiveButton("Sil",(d,w)->{JSONArray next=new JSONArray();for(int i=0;i<cards.length();i++){JSONObject o=cards.optJSONObject(i);if(o!=null&&!id.equals(o.optString("id")))next.put(o);}cards=next;save();collection("");}).show();}
  void folders(){screen("Klasörler");java.util.TreeSet<String> names=new java.util.TreeSet<>();for(int i=0;i<cards.length();i++){JSONObject o=cards.optJSONObject(i);if(o!=null&&!o.optString("folder").trim().isEmpty())names.add(o.optString("folder"));}if(names.isEmpty())content.addView(label("Henüz klasör yok. Kart eklerken klasör adı yazabilirsin.",15,false));for(String name:names)button("▤ "+name,()->collectionByFolder(name));button("← Ana sayfa",()->home());}
  void collectionByFolder(String folder){screen("Klasör: "+folder);for(int i=0;i<cards.length();i++){JSONObject o=cards.optJSONObject(i);if(o!=null&&folder.equals(o.optString("folder"))){final String id=o.optString("id");content.addView(label(o.optString("name"),17,true));button("Düzenle",()->edit(id));}}button("← Klasörler",()->folders());}
  void edit(String id){JSONObject card=null;for(int i=0;i<cards.length();i++){JSONObject o=cards.optJSONObject(i);if(o!=null&&id.equals(o.optString("id"))){card=o;break;}}if(card==null){message("Kart bulunamadı");return;}final JSONObject target=card;screen("Kartı düzenle");String[] keys={"name","sport","brand","year","number","variant","price","cost","folder","grade","notes"};String[] hints={"Kart adı","Spor / TCG","Marka / set","Yıl","Kart numarası","Varyant","Tahmini değer USD","Alış fiyatı USD","Klasör","Kondisyon","Notlar"};EditText[] fields=new EditText[keys.length];for(int i=0;i<keys.length;i++){fields[i]=field(hints[i]);fields[i].setText(card.optString(keys[i]));}button("Değişiklikleri kaydet",()->{try{for(int i=0;i<keys.length;i++)target.put(keys[i],fields[i].getText().toString());save();collection("");}catch(Exception e){message("Kaydetme hatası");}});}
  void importBackup(){screen("JSON yedeği içe aktar");content.addView(label("Yedek JSON metnini yapıştır. Mevcut kartlar korunur; aynı ID tekrar eklenmez.",15,false));EditText data=field("JSON koleksiyon dizisi");data.setMinLines(5);button("Kartları içe aktar",()->{try{JSONArray incoming=new JSONArray(data.getText().toString());HashSet<String> ids=new HashSet<>();for(int i=0;i<cards.length();i++)ids.add(cards.optJSONObject(i).optString("id"));int added=0;for(int i=0;i<incoming.length();i++){JSONObject o=incoming.optJSONObject(i);if(o==null||o.optString("name").trim().isEmpty())continue;String id=o.optString("id");if(id.isEmpty()){id=UUID.randomUUID().toString();o.put("id",id);}if(ids.add(id)){cards.put(o);added++;}}save();message(added+" kart içe aktarıldı.");}catch(Exception e){message("Geçersiz JSON. İşlem iptal edildi.");}});button("← Ana sayfa",()->home());}
  void favorites(){screen("Favoriler");for(int i=0;i<cards.length();i++){JSONObject o=cards.optJSONObject(i);if(o!=null&&o.optBoolean("favorite"))content.addView(label("★ "+o.optString("name"),17,false));}button("← Ana sayfa",()->home());}
  void portfolio(){screen("Portföy");double sum=0,cost=0;for(int i=0;i<cards.length();i++){JSONObject o=cards.optJSONObject(i);if(o!=null)try{sum+=Double.parseDouble(o.optString("price","0"));}catch(Exception ignored){}}for(int i=0;i<cards.length();i++){JSONObject o=cards.optJSONObject(i);if(o!=null)try{cost+=Double.parseDouble(o.optString("cost","0"));}catch(Exception ignored){}}content.addView(label(String.format(Locale.US,"Toplam manuel değer: $%.2f",sum),23,true));content.addView(label(String.format(Locale.US,"Toplam alış: $%.2f  •  Fark: $%.2f",cost,sum-cost),16,false));content.addView(label("Bu değer canlı piyasa verisi değildir.",14,false));button("← Ana sayfa",()->home());}
  void export(){Intent intent=new Intent(Intent.ACTION_SEND);intent.setType("application/json");intent.putExtra(Intent.EXTRA_TEXT,cards.toString());startActivity(Intent.createChooser(intent,"Koleksiyonu paylaş"));}
  void status(){screen("Bağlantılar");content.addView(label("Yerel koleksiyon: Çalışır\nAI kart tanıma: Henüz bağlı değil\nCanlı fiyat verisi: Henüz bağlı değil\nBulut hesapları: Henüz bağlı değil\nPazaryeri ve eBay: Henüz bağlı değil\nPremium ödeme: Henüz bağlı değil",16,false));button("← Ana sayfa",()->home());}
}